"""Tensor-parallel linear layers (Megatron-style).

Weight layout follows torch.nn.Linear: weight has shape (out_features, in_features).

- ColumnParallelLinear: the output dimension is partitioned across ranks.
  Each rank computes Y_i = X W_i^T + b_i and the partial outputs are
  concatenated along the last dimension (all_gather).
- RowParallelLinear: the input dimension is partitioned across ranks.
  Each rank computes Y_i = X_i W_i^T and the partial outputs are summed
  (all_reduce); the full bias is then added on every rank.
"""

import torch
import torch.distributed as dist
import torch.nn as nn
import torch.nn.functional as F


def _dist_ready():
    return dist.is_available() and dist.is_initialized()


def _world_size():
    return dist.get_world_size() if _dist_ready() else 1


def _rank():
    return dist.get_rank() if _dist_ready() else 0


def _divide(numerator, denominator):
    if numerator % denominator != 0:
        raise ValueError(f"{numerator} is not divisible by {denominator}")
    return numerator // denominator


# --------------------------------------------------------------------------- #
# Autograd-aware communication primitives
# --------------------------------------------------------------------------- #
def _all_reduce(x):
    if _world_size() == 1:
        return x
    x = x.contiguous().clone()
    dist.all_reduce(x, op=dist.ReduceOp.SUM)
    return x


def _split_last_dim(x):
    ws = _world_size()
    if ws == 1:
        return x
    chunk = _divide(x.shape[-1], ws)
    r = _rank()
    return x[..., r * chunk:(r + 1) * chunk].contiguous()


def _gather_last_dim(x):
    ws = _world_size()
    if ws == 1:
        return x
    x = x.contiguous()
    parts = [torch.empty_like(x) for _ in range(ws)]
    dist.all_gather(parts, x)
    return torch.cat(parts, dim=-1).contiguous()


class _CopyToParallelRegion(torch.autograd.Function):
    """Forward: identity. Backward: all-reduce of the gradient."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad):
        return _all_reduce(grad)


class _ReduceFromParallelRegion(torch.autograd.Function):
    """Forward: all-reduce. Backward: identity."""

    @staticmethod
    def forward(ctx, x):
        return _all_reduce(x)

    @staticmethod
    def backward(ctx, grad):
        return grad


class _ScatterToParallelRegion(torch.autograd.Function):
    """Forward: take this rank's slice of last dim. Backward: all-gather."""

    @staticmethod
    def forward(ctx, x):
        return _split_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        return _gather_last_dim(grad)


class _GatherFromParallelRegion(torch.autograd.Function):
    """Forward: all-gather along last dim. Backward: take this rank's slice."""

    @staticmethod
    def forward(ctx, x):
        return _gather_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        return _split_last_dim(grad)


# --------------------------------------------------------------------------- #
# Layers
# --------------------------------------------------------------------------- #
class ColumnParallelLinear(nn.Module):
    """Linear layer whose weight is split along the output dimension."""

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        self.out_features_per_partition = _divide(out_features, self.world_size)

        if tuple(master_weight.shape) != (out_features, in_features):
            raise ValueError(
                f"master_weight shape {tuple(master_weight.shape)} does not match "
                f"(out_features, in_features) = {(out_features, in_features)}"
            )

        start = self.rank * self.out_features_per_partition
        end = start + self.out_features_per_partition
        with torch.no_grad():
            shard = master_weight.detach()[start:end, :].clone().contiguous()
        self.weight = nn.Parameter(shard)

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    self.out_features_per_partition,
                    dtype=master_weight.dtype,
                    device=master_weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        x = _CopyToParallelRegion.apply(x)
        local_out = F.linear(x, self.weight, self.bias)
        return _GatherFromParallelRegion.apply(local_out)


class RowParallelLinear(nn.Module):
    """Linear layer whose weight is split along the input dimension."""

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        self.in_features_per_partition = _divide(in_features, self.world_size)

        if tuple(master_weight.shape) != (out_features, in_features):
            raise ValueError(
                f"master_weight shape {tuple(master_weight.shape)} does not match "
                f"(out_features, in_features) = {(out_features, in_features)}"
            )

        start = self.rank * self.in_features_per_partition
        end = start + self.in_features_per_partition
        with torch.no_grad():
            shard = master_weight.detach()[:, start:end].clone().contiguous()
        self.weight = nn.Parameter(shard)

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    out_features,
                    dtype=master_weight.dtype,
                    device=master_weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        # Accept either the full input (split it here) or an already
        # partitioned input (e.g. the output of a ColumnParallelLinear shard).
        if x.shape[-1] == self.in_features_per_partition and self.world_size > 1 \
                and self.in_features != self.in_features_per_partition:
            x_parallel = x
        else:
            x_parallel = _ScatterToParallelRegion.apply(x)
        partial = F.linear(x_parallel, self.weight)
        out = _ReduceFromParallelRegion.apply(partial)
        if self.bias is not None:
            out = out + self.bias
        return out
